package com.hbm.client.reactor.pile.core;
import com.hbm.client.gui.font.LegacyFonts;import com.hbm.machine.reactor.pile.core.*;import java.util.*;import net.minecraft.client.Minecraft;import net.minecraft.network.chat.Component;import net.minecraft.world.phys.BlockHitResult;import net.neoforged.api.distmarker.Dist;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.neoforge.client.event.RenderGuiLayerEvent;import net.neoforged.neoforge.client.gui.VanillaGuiLayers;
/** Source yellow title/olive shadow, ten-pixel rows, and exact CP readout rounding. */
@EventBusSubscriber(modid="hbm",value=Dist.CLIENT)
public final class PileOverlay {
 public static List<Component> lines(PileTickingBlockEntity tile){var lines=new ArrayList<Component>();if(tile instanceof TileEntityPileCore core)lines.add(Component.translatable("hud.hbm.pile.max_temp",(int)Math.round(core.highestHeat),800));else if(tile instanceof TileEntityPileBaseMK2 part){String label=switch(part.getBlockMetadata()){case 3->"fuel_in";case 4->"fuel_out";case 5->"air_in";case 6->"air_out";case 7->"control_channel";default->null;};if(label!=null)lines.add(Component.translatable("hud.hbm.pile."+label));}else if(tile instanceof TileEntityPileLoader loader){lines.add(Component.translatable("hud.hbm.pile.temp",(int)Math.round(loader.channelTemp),800));if(loader.syncStack!=null)lines.add(Component.translatable("hud.hbm.pile.loading",loader.syncStack.getHoverName()));if(loader.channelStack!=null){lines.add(Component.translatable("hud.hbm.pile.last_rod",loader.channelStack.getHoverName()));if(loader.channelDepletion>0)lines.add(Component.translatable("hud.hbm.pile.depletion",(int)Math.round(loader.channelDepletion)));}}else if(tile instanceof TileEntityPileControl control)lines.add(Component.translatable("hud.hbm.pile.extraction",(int)(control.level*100)));return lines;}
 public static Component title(PileTickingBlockEntity tile){if(tile instanceof TileEntityPileDeviceBase)return Component.translatable("tile.pile_device."+new String[]{"loader","vent","control"}[tile.getBlockMetadata()/4]+".name");return Component.translatable("tile.pile_block.name");}
 @SubscribeEvent public static void render(RenderGuiLayerEvent.Pre event){if(!com.hbm.item.settings.client.LegacyInfoSystem.lookOverlayEnabled())return;if(!event.getName().equals(VanillaGuiLayers.CROSSHAIR))return;var client=Minecraft.getInstance();if(client.options.hideGui||client.level==null||!(client.hitResult instanceof BlockHitResult hit)||!(client.level.getBlockEntity(hit.getBlockPos()) instanceof PileTickingBlockEntity tile))return;var lines=lines(tile);if(lines.isEmpty())return;var graphics=event.getGuiGraphics();var font=LegacyFonts.get();int x=graphics.guiWidth()/2+8,y=graphics.guiHeight()/2;var title=title(tile);graphics.drawString(font,title,x+1,y-9,0x404000,false);graphics.drawString(font,title,x,y-10,0xffff00,false);for(int i=0;i<lines.size();i++)graphics.drawString(font,lines.get(i),x,y+i*10,0xffffff,true);}
 private PileOverlay(){}
}
